document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-panel");e.forEach(d=>{d.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),d.classList.add("active"),document.getElementById(`tab-${d.dataset.tab}`)?.classList.add("active")})});const d=document.getElementById("toggleReviewForm"),a=document.getElementById("addReviewForm");d&&a&&d.addEventListener("click",()=>{a.hidden=!a.hidden})});